package main

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func TestClassifyMatrixInvalidFromFixtures(t *testing.T) {
	cases := []struct {
		name string
		want string
	}{
		{name: "claude-quota.json", want: matrixInvalidQuota},
		{name: "codex-auth.json", want: matrixInvalidAuth},
		{name: "pi-missing-binary.json", want: matrixInvalidSetup},
		{name: "opencode-account.json", want: matrixInvalidAuth},
		{name: "opencode-wrapper-startup.json", want: matrixInvalidSetup},
		{name: "setup-native-arch.json", want: matrixInvalidSetup},
		{name: "provider-transport.json", want: matrixInvalidProvider},
		{name: "verifier-fail-after-attempt.json", want: ""},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			report := loadMatrixInvalidFixture(t, tc.name)
			if got := classifyMatrixInvalid(report); got != tc.want {
				t.Fatalf("classifyMatrixInvalid(%s) = %q, want %q", tc.name, got, tc.want)
			}
		})
	}
}

func TestMatrixAggregateIncludesInvalidCountsAndSkipsInvalidDenominators(t *testing.T) {
	outDir := t.TempDir()

	valid := matrixRunReport{
		Harness:        "claude",
		ProfileID:      "gpt-5-4-mini",
		Rep:            1,
		TaskID:         "fix-git",
		ProcessOutcome: "completed",
		GradingOutcome: "graded",
		Reward:         intPtr(1),
		FinalStatus:    "graded_pass",
		Turns:          intPtr(5),
		ToolCalls:      intPtr(7),
		InputTokens:    intPtr(100),
		OutputTokens:   intPtr(50),
		StartedAt:      time.Now().UTC(),
		FinishedAt:     time.Now().UTC(),
	}
	writeFixtureRun(t, outDir, valid)

	invalidQuota := loadMatrixInvalidFixture(t, "claude-quota.json")
	invalidQuota.Rep = 2
	invalidQuota.TaskID = "fix-git"
	writeFixtureRun(t, outDir, invalidQuota)

	for _, name := range []string{
		"codex-auth.json",
		"pi-missing-binary.json",
		"opencode-account.json",
		"opencode-wrapper-startup.json",
		"setup-native-arch.json",
		"verifier-fail-after-attempt.json",
	} {
		writeFixtureRun(t, outDir, loadMatrixInvalidFixture(t, name))
	}

	providerTransport := loadMatrixInvalidFixture(t, "provider-transport.json")
	providerTransport.Harness = "provider-transport"
	providerTransport.ProfileID = "provider-sim"
	providerTransport.Rep = 1
	providerTransport.TaskID = "git-leak-recovery"
	writeFixtureRun(t, outDir, providerTransport)

	if code := cmdMatrixAggregate([]string{outDir}); code != 0 {
		t.Fatalf("cmdMatrixAggregate exit = %d, want 0", code)
	}

	matrix := readMatrixOutput(t, filepath.Join(outDir, "matrix.json"))
	if got, want := matrix.InvalidRuns, 7; got != want {
		t.Fatalf("invalid_runs = %d, want %d", got, want)
	}
	wantInvalidByClass := map[string]int{
		matrixInvalidQuota:    1,
		matrixInvalidAuth:     2,
		matrixInvalidSetup:    3,
		matrixInvalidProvider: 1,
	}
	if len(matrix.InvalidByClass) != len(wantInvalidByClass) {
		t.Fatalf("invalid_by_class len = %d, want %d", len(matrix.InvalidByClass), len(wantInvalidByClass))
	}
	for class, want := range wantInvalidByClass {
		if got := matrix.InvalidByClass[class]; got != want {
			t.Fatalf("invalid_by_class[%s] = %d, want %d", class, got, want)
		}
	}

	var claudeCell *matrixCell
	for i := range matrix.Cells {
		if matrix.Cells[i].Harness == "claude" && matrix.Cells[i].ProfileID == "gpt-5-4-mini" {
			claudeCell = &matrix.Cells[i]
			break
		}
	}
	if claudeCell == nil {
		t.Fatal("claude cell missing")
	}
	if claudeCell.NRuns != 2 || claudeCell.NValid != 1 || claudeCell.NInvalid != 1 || claudeCell.NReported != 1 {
		t.Fatalf("claude counts = %+v, want NRuns=2 NValid=1 NInvalid=1 NReported=1", *claudeCell)
	}
	if got := claudeCell.InvalidCounts[matrixInvalidQuota]; got != 1 {
		t.Fatalf("claude invalid counts = %#v, want invalid_quota=1", claudeCell.InvalidCounts)
	}
	if claudeCell.MeanReward == nil || *claudeCell.MeanReward != 1 {
		t.Fatalf("claude mean reward = %v, want 1", claudeCell.MeanReward)
	}

	rawMD, err := os.ReadFile(filepath.Join(outDir, "matrix.md"))
	if err != nil {
		t.Fatal(err)
	}
	md := string(rawMD)
	for _, want := range []string{
		"## Invalid runs",
		"invalid_quota",
		"invalid_auth",
		"invalid_setup",
		"invalid_provider",
		"1.00 +/- 0.00 (n=1/1)",
		"1/1 |",
	} {
		if !strings.Contains(md, want) {
			t.Fatalf("matrix.md missing %q:\n%s", want, md)
		}
	}
}

func loadMatrixInvalidFixture(t *testing.T, name string) matrixRunReport {
	t.Helper()
	path := filepath.Join("testdata", "matrix-invalid", name)
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read fixture %s: %v", name, err)
	}
	var report matrixRunReport
	if err := json.Unmarshal(raw, &report); err != nil {
		t.Fatalf("parse fixture %s: %v", name, err)
	}
	return report
}

package main

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/benchmark/profile"
)

func TestMatrixNoopDumbScriptProducesValidMatrix(t *testing.T) {
	repoRoot := benchRepoRoot(t)
	outDir := t.TempDir()

	code := cmdMatrix([]string{
		"--work-dir", repoRoot,
		"--harnesses", "noop,dumb_script",
		"--profiles", "noop",
		"--reps", "2",
		"--out", outDir,
	})
	if code != 0 {
		t.Fatalf("cmdMatrix exit = %d, want 0", code)
	}

	matrix := readMatrixOutput(t, filepath.Join(outDir, "matrix.json"))
	if got, want := len(matrix.Runs), 12; got != want {
		t.Fatalf("runs = %d, want %d", got, want)
	}
	for _, run := range matrix.Runs {
		if run.Harness == "" || run.ProfileID == "" || run.TaskID == "" {
			t.Fatalf("incomplete run identity: %+v", run)
		}
		if run.AdapterModule == "" || run.HarborAgent == "" {
			t.Fatalf("missing adapter path metadata: %+v", run)
		}
		if run.FinalStatus == "" {
			t.Fatalf("missing final_status: %+v", run)
		}
		if _, err := os.Stat(filepath.Join(run.OutputDir, matrixReportName)); err != nil {
			t.Fatalf("report missing for %s/%s/%s: %v", run.Harness, run.ProfileID, run.TaskID, err)
		}
	}
}

func TestMatrixResumeSkipsTerminalReport(t *testing.T) {
	repoRoot := benchRepoRoot(t)
	outDir := t.TempDir()

	args := []string{
		"--work-dir", repoRoot,
		"--harnesses", "dumb_script",
		"--profiles", "noop",
		"--reps", "1",
		"--out", outDir,
	}
	if code := cmdMatrix(args); code != 0 {
		t.Fatalf("initial cmdMatrix exit = %d, want 0", code)
	}

	reportPath := filepath.Join(outDir, "cells", "dumb_script", "noop", "rep-001", "fix-git", matrixReportName)
	before, err := os.Stat(reportPath)
	if err != nil {
		t.Fatalf("stat report: %v", err)
	}
	time.Sleep(20 * time.Millisecond)
	if code := cmdMatrix(append(args, "--resume")); code != 0 {
		t.Fatalf("resume cmdMatrix exit = %d, want 0", code)
	}
	after, err := os.Stat(reportPath)
	if err != nil {
		t.Fatalf("stat report after resume: %v", err)
	}
	if !after.ModTime().Equal(before.ModTime()) {
		t.Fatalf("terminal report was rewritten on resume: before=%s after=%s", before.ModTime(), after.ModTime())
	}
}

func TestMatrixLockPreventsDoubleSpend(t *testing.T) {
	repoRoot := benchRepoRoot(t)
	outDir := t.TempDir()
	lockPath := filepath.Join(outDir, "cells", "noop", "noop", "rep-001", "fix-git", matrixLockName)
	if err := os.MkdirAll(filepath.Dir(lockPath), 0o750); err != nil {
		t.Fatal(err)
	}
	lock := matrixLock{PID: os.Getpid(), StartedAt: time.Now().UTC()}
	raw, _ := json.Marshal(lock)
	if err := os.WriteFile(lockPath, raw, 0o600); err != nil {
		t.Fatal(err)
	}

	code := cmdMatrix([]string{
		"--work-dir", repoRoot,
		"--harnesses", "noop",
		"--profiles", "noop",
		"--reps", "1",
		"--out", outDir,
	})
	if code == 0 {
		t.Fatal("cmdMatrix succeeded despite live tuple lock")
	}
	if _, err := os.Stat(filepath.Join(filepath.Dir(lockPath), matrixReportName)); !os.IsNotExist(err) {
		t.Fatalf("locked tuple should not write report, stat err=%v", err)
	}
}

func TestMatrixResumeAfterStaleLockMatchesCleanRun(t *testing.T) {
	repoRoot := benchRepoRoot(t)
	cleanOut := t.TempDir()
	resumeOut := t.TempDir()

	args := []string{
		"--work-dir", repoRoot,
		"--harnesses", "dumb_script",
		"--profiles", "noop",
		"--reps", "1",
	}
	if code := cmdMatrix(append(args, "--out", cleanOut)); code != 0 {
		t.Fatalf("clean cmdMatrix exit = %d, want 0", code)
	}

	lockPath := filepath.Join(resumeOut, "cells", "dumb_script", "noop", "rep-001", "fix-git", matrixLockName)
	if err := os.MkdirAll(filepath.Dir(lockPath), 0o750); err != nil {
		t.Fatal(err)
	}
	lock := matrixLock{PID: -1, StartedAt: time.Now().UTC().Add(-time.Minute)}
	raw, _ := json.Marshal(lock)
	if err := os.WriteFile(lockPath, raw, 0o600); err != nil {
		t.Fatal(err)
	}
	if code := cmdMatrix(append(args, "--out", resumeOut, "--resume")); code != 0 {
		t.Fatalf("resume cmdMatrix exit = %d, want 0", code)
	}

	clean := readMatrixOutput(t, filepath.Join(cleanOut, "matrix.json"))
	resumed := readMatrixOutput(t, filepath.Join(resumeOut, "matrix.json"))
	if len(clean.Runs) != len(resumed.Runs) {
		t.Fatalf("resumed run count = %d, want %d", len(resumed.Runs), len(clean.Runs))
	}
	for i := range clean.Runs {
		if clean.Runs[i].Harness != resumed.Runs[i].Harness ||
			clean.Runs[i].ProfileID != resumed.Runs[i].ProfileID ||
			clean.Runs[i].Rep != resumed.Runs[i].Rep ||
			clean.Runs[i].TaskID != resumed.Runs[i].TaskID ||
			clean.Runs[i].FinalStatus != resumed.Runs[i].FinalStatus {
			t.Fatalf("resumed run[%d] mismatch:\nclean=%+v\nresumed=%+v", i, clean.Runs[i], resumed.Runs[i])
		}
		if clean.Runs[i].Reward == nil && resumed.Runs[i].Reward != nil ||
			clean.Runs[i].Reward != nil && resumed.Runs[i].Reward == nil ||
			clean.Runs[i].Reward != nil && resumed.Runs[i].Reward != nil && *clean.Runs[i].Reward != *resumed.Runs[i].Reward {
			t.Fatalf("resumed reward[%d] mismatch", i)
		}
	}
}

func TestMatrixOverBudgetRunBecomesBudgetHaltedAndContinues(t *testing.T) {
	repoRoot := benchRepoRoot(t)
	outDir := t.TempDir()

	code := cmdMatrix([]string{
		"--work-dir", repoRoot,
		"--harnesses", "cost_probe",
		"--profiles", "smoke",
		"--reps", "2",
		"--per-run-budget-usd", "0.000001",
		"--out", outDir,
	})
	if code != 0 {
		t.Fatalf("cmdMatrix exit = %d, want 0", code)
	}
	matrix := readMatrixOutput(t, filepath.Join(outDir, "matrix.json"))
	if got, want := len(matrix.Runs), 6; got != want {
		t.Fatalf("runs = %d, want %d", got, want)
	}
	for _, run := range matrix.Runs {
		if run.FinalStatus != "budget_halted" {
			t.Fatalf("run %s/%d final_status = %s, want budget_halted", run.TaskID, run.Rep, run.FinalStatus)
		}
		if run.CostUSD <= 0 {
			t.Fatalf("run %s/%d cost = %f, want > 0", run.TaskID, run.Rep, run.CostUSD)
		}
	}
}

