func benchRepoRoot(t *testing.T) string {
	t.Helper()
	wd, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	return filepath.Clean(filepath.Join(wd, "..", ".."))
}

func readMatrixOutput(t *testing.T, path string) matrixOutput {
	t.Helper()
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read matrix output: %v", err)
	}
	var out matrixOutput
	if err := json.Unmarshal(raw, &out); err != nil {
		t.Fatalf("parse matrix output: %v", err)
	}
	return out
}

package main

import (
	"regexp"
	"strings"
)

const (
	matrixInvalidQuota    = "invalid_quota"
	matrixInvalidAuth     = "invalid_auth"
	matrixInvalidSetup    = "invalid_setup"
	matrixInvalidProvider = "invalid_provider"
)

var (
	matrixInvalidQuotaPattern    = regexp.MustCompile(`(?i)(api_error_status:\s*429|out_of_credits|credits?\s+exhausted|usage\s+exhausted|rate\s*limit|too many requests|quota\s+exhausted|quota\s+exceeded)`)
	matrixInvalidAuthPattern     = regexp.MustCompile(`(?i)(unauthori[sz]ed|authentication failed|invalid api key|missing credentials?|not signed in|login required|account .*not .*authenticated|oauth.*failed|credential.*missing|account .*required|access denied)`)
	matrixInvalidSetupPattern    = regexp.MustCompile(`(?i)(binary not found|no such file or directory|exec format error|cannot execute binary file|wrong architecture|architecture mismatch|task dir not found|submodule not initialized|failed to start|wrapper startup|startup failed|docker.*(failed|error)|container.*(failed|error)|image.*(failed|error|not found)|operation not permitted|permission denied|sandbox.*failed|setup failed|preflight failure)`)
	matrixInvalidProviderPattern = regexp.MustCompile(`(?i)(connection refused|connection reset|socket hang up|fetch failed|tls handshake|dns|eof|timed out|timeout|stream closed|broken pipe|remote closed|upstream|service unavailable|bad gateway|gateway timeout|failed to connect|provider transport|network error)`)
)

func classifyMatrixInvalid(report matrixRunReport) string {
	switch report.FinalStatus {
	case "graded_pass", "graded_fail", "verifier_fail":
		return ""
	}
	if isMatrixKnownInvalidClass(report.FinalStatus) {
		return report.FinalStatus
	}
	if report.InvalidClass != "" {
		return report.InvalidClass
	}
	if matrixHasMeaningfulAttempt(report) {
		return ""
	}
	blob := matrixInvalidSignalBlob(report)
	switch {
	case matrixInvalidQuotaPattern.MatchString(blob):
		return matrixInvalidQuota
	case matrixInvalidAuthPattern.MatchString(blob):
		return matrixInvalidAuth
	case matrixInvalidSetupPattern.MatchString(blob):
		return matrixInvalidSetup
	case matrixInvalidProviderPattern.MatchString(blob):
		return matrixInvalidProvider
	default:
		return ""
	}
}

func isMatrixKnownInvalidClass(status string) bool {
	switch status {
	case matrixInvalidQuota, matrixInvalidAuth, matrixInvalidSetup, matrixInvalidProvider:
		return true
	default:
		return false
	}
}

func matrixHasMeaningfulAttempt(report matrixRunReport) bool {
	return intValue(report.Turns) > 0 ||
		intValue(report.ToolCalls) > 0 ||
		intValue(report.ToolCallErrors) > 0 ||
		intValue(report.InputTokens) > 0 ||
		intValue(report.OutputTokens) > 0 ||
		intValue(report.CachedInputTokens) > 0 ||
		intValue(report.RetriedInputTokens) > 0
}

func matrixInvalidSignalBlob(report matrixRunReport) string {
	parts := []string{
		report.Error,
		report.ProcessOutcome,
		report.FinalStatus,
		strings.Join(report.AdapterTranslationNotes, " "),
		strings.Join(report.Command, " "),
	}
	var out []string
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part != "" {
			out = append(out, part)
		}
	}
	return strings.ToLower(strings.Join(out, "\n"))
}

func samplingEnvPairs(p *profile.Profile) []string {
	var pairs []string
	pairs = append(pairs, fmt.Sprintf("FIZEAU_TEMPERATURE=%g", p.Sampling.Temperature))
	if p.Sampling.TopP != nil {
		pairs = append(pairs, fmt.Sprintf("FIZEAU_TOP_P=%g", *p.Sampling.TopP))
	}
	if p.Sampling.TopK != nil {
		pairs = append(pairs, fmt.Sprintf("FIZEAU_TOP_K=%d", *p.Sampling.TopK))
	}
	if p.Sampling.MinP != nil {
		pairs = append(pairs, fmt.Sprintf("FIZEAU_MIN_P=%g", *p.Sampling.MinP))
	}
	return pairs
}

func fizeauProviderEnv(p *profile.Profile) string {
	if p.Provider.Type == profile.ProviderOpenAICompat && strings.Contains(p.Provider.BaseURL, "openrouter") {
		return string(profile.ProviderOpenRouter)
	}
	if p.Provider.Type == profile.ProviderOpenAICompat && strings.Contains(p.Provider.BaseURL, "vidar:1235") {
		return string(profile.ProviderOMLX)
	}
	return string(p.Provider.Type)
}

func truthyEnv(name string) bool {
	switch strings.ToLower(strings.TrimSpace(os.Getenv(name))) {
	case "1", "true", "yes", "y", "on":
		return true
	default:
		return false
	}
}

// queryModelServerInfo attempts to fetch model metadata from a lmstudio
// /api/v0/models/<id> endpoint. Returns nil if the server is not lmstudio
// or the request fails.
func queryModelServerInfo(p *profile.Profile) *profile.ModelServerInfo {
	base := strings.TrimRight(p.Provider.BaseURL, "/")
	// Only try lmstudio-style endpoints (port 1234 conventional, or path /api/v0 present).
	if !strings.Contains(base, ":1234") && !strings.Contains(base, "/api/v0") {
		return nil
	}
	// Strip trailing /v1 to get the base server URL.
	apiBase := strings.TrimSuffix(base, "/v1")
	modelID := p.Provider.Model
	url := apiBase + "/api/v0/models/" + modelID

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil || resp.StatusCode != http.StatusOK {
		return nil
	}
	defer resp.Body.Close()
	var info struct {
		Quantization        string `json:"quantization"`
		LoadedContextLength int    `json:"loaded_context_length"`
		MaxContextLength    int    `json:"max_context_length"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&info); err != nil {
		return nil
	}
	return &profile.ModelServerInfo{
		Quantization:        info.Quantization,
		LoadedContextLength: info.LoadedContextLength,
		MaxContextLength:    info.MaxContextLength,
		Source:              url,
	}
}

// Package profile is the canonical reader for v7 benchmark profile YAML files
// under scripts/benchmark/profiles/. The schema is frozen by SD-010 §3
// (Harness × Model Matrix Benchmark); additive fields require a spec amendment.
package profile

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

// ProviderType enumerates the four provider client paths supported by the
// matrix runner. SD-010 §3 forbids silent override; the adapter selects its
// client path by exact match on this field.
type ProviderType string

const (
	ProviderAnthropic    ProviderType = "anthropic"
	ProviderOpenAI       ProviderType = "openai"
	ProviderOpenAICompat ProviderType = "openai-compat"
	ProviderOpenRouter   ProviderType = "openrouter"
	ProviderOMLX         ProviderType = "omlx"
	ProviderLMStudio     ProviderType = "lmstudio"
	ProviderOllama       ProviderType = "ollama"
	ProviderGoogle       ProviderType = "google"
)

func (p ProviderType) valid() bool {
	switch p {
	case ProviderAnthropic, ProviderOpenAI, ProviderOpenAICompat, ProviderOpenRouter,
		ProviderOMLX, ProviderLMStudio, ProviderOllama, ProviderGoogle:
		return true
	}
	return false
}

// Provider describes how the harness adapter should reach the model API.
type Provider struct {
	Type      ProviderType `yaml:"type"`
	Model     string       `yaml:"model"`
	BaseURL   string       `yaml:"base_url"`
	APIKeyEnv string       `yaml:"api_key_env"`
}

// Pricing is the single source of truth for cost reconciliation. Units are
// USD per million tokens.
type Pricing struct {
	InputUSDPerMTok       float64 `yaml:"input_usd_per_mtok"`
	OutputUSDPerMTok      float64 `yaml:"output_usd_per_mtok"`
	CachedInputUSDPerMTok float64 `yaml:"cached_input_usd_per_mtok"`
}

// Limits captures provider-side ceilings. rate_limit_* are informational in
// v1 (D6 forbids concurrency > 1) and reserved for the follow-up scheduler.
type Limits struct {
	MaxOutputTokens int `yaml:"max_output_tokens"`
	ContextTokens   int `yaml:"context_tokens"`
	RateLimitRPM    int `yaml:"rate_limit_rpm"`
	RateLimitTPM    int `yaml:"rate_limit_tpm"`
}

// Sampling is opaque to the runner; passed verbatim to the adapter's
// apply_profile step. Reasoning is a free-form string ("low" | "medium" |
// "high" | "" depending on the family). Pointer fields are omitted when
// nil so server defaults apply.
type Sampling struct {
	Temperature float64  `yaml:"temperature"`
	Reasoning   string   `yaml:"reasoning,omitempty"`
	TopP        *float64 `yaml:"top_p,omitempty"`
	TopK        *int     `yaml:"top_k,omitempty"`
	MinP        *float64 `yaml:"min_p,omitempty"`
}

// ModelServerInfo is populated at run time by querying the local model server
// (e.g. lmstudio /api/v0/models/<id>). Fields are empty/zero when the server
// does not expose them.
type ModelServerInfo struct {
	Quantization        string `json:"quantization,omitempty"`
	LoadedContextLength int    `json:"loaded_context_length,omitempty"`
	MaxContextLength    int    `json:"max_context_length,omitempty"`
	Source              string `json:"source,omitempty"` // URL queried
}

// Versioning records when the profile was authored and which provider
// snapshot the adapter resolved at apply_profile time.
type Versioning struct {
	ResolvedAt string `yaml:"resolved_at"`
	Snapshot   string `yaml:"snapshot"`
}

// Profile is the in-memory shape of a frozen v1 profile YAML.
type Profile struct {
	ID         string     `yaml:"id"`
	Provider   Provider   `yaml:"provider"`
	Pricing    Pricing    `yaml:"pricing"`
	Limits     Limits     `yaml:"limits"`
	Sampling   Sampling   `yaml:"sampling"`
	Versioning Versioning `yaml:"versioning"`

	// Path is the filesystem path the profile was loaded from. Not part of
	// the YAML; populated by Load / LoadDir for diagnostics and `profiles
	// list` output.
	Path string `yaml:"-"`
}

// Load reads and validates a single profile YAML file at path.
func Load(path string) (*Profile, error) {
	raw, err := os.ReadFile(path) // #nosec G304 -- path is an operator-supplied profile location, scoped by Validate()
	if err != nil {
		return nil, fmt.Errorf("read profile %s: %w", path, err)
	}
	var p Profile
	dec := yaml.NewDecoder(strings.NewReader(string(raw)))
	dec.KnownFields(true)
	if err := dec.Decode(&p); err != nil {
		return nil, fmt.Errorf("parse profile %s: %w", path, err)
	}
	p.Path = path
	if err := p.Validate(); err != nil {
		return nil, fmt.Errorf("validate profile %s: %w", path, err)
	}
	return &p, nil
}

// LoadDir loads every *.yaml / *.yml file under dir, sorted by id. It is the
// entry point used by `fiz-bench profiles list`.
func LoadDir(dir string) ([]*Profile, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("read profiles dir %s: %w", dir, err)
	}
	var profiles []*Profile
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		ext := strings.ToLower(filepath.Ext(e.Name()))
		if ext != ".yaml" && ext != ".yml" {
			continue
		}
		p, err := Load(filepath.Join(dir, e.Name()))
		if err != nil {
			return nil, err
		}
		profiles = append(profiles, p)
	}
	sort.Slice(profiles, func(i, j int) bool { return profiles[i].ID < profiles[j].ID })
	return profiles, nil
}

// Validate checks that every required v1 field is present. The schema is
// frozen by SD-010 §3; missing fields are a hard error rather than a warning.
func (p *Profile) Validate() error {
	if strings.TrimSpace(p.ID) == "" {
		return fmt.Errorf("id is required")
	}
	if !p.Provider.Type.valid() {
		return fmt.Errorf("provider.type %q is not one of anthropic|openai|openrouter|omlx|lmstudio|ollama|google", p.Provider.Type)
	}
	if strings.TrimSpace(p.Provider.Model) == "" {
		return fmt.Errorf("provider.model is required")
	}
	if strings.TrimSpace(p.Provider.BaseURL) == "" {
		return fmt.Errorf("provider.base_url is required")
	}
	if strings.TrimSpace(p.Provider.APIKeyEnv) == "" {
		return fmt.Errorf("provider.api_key_env is required")
	}
	if p.Pricing.InputUSDPerMTok < 0 || p.Pricing.OutputUSDPerMTok < 0 || p.Pricing.CachedInputUSDPerMTok < 0 {
		return fmt.Errorf("pricing.* must be non-negative")
	}
	if p.Limits.MaxOutputTokens <= 0 {
		return fmt.Errorf("limits.max_output_tokens must be > 0")
	}
	if p.Limits.ContextTokens <= 0 {
		return fmt.Errorf("limits.context_tokens must be > 0")
	}
	if strings.TrimSpace(p.Versioning.ResolvedAt) == "" {
		return fmt.Errorf("versioning.resolved_at is required")
	}
	return nil
}

