 62	func compileBenchmarkEvidenceSchema(t *testing.T) *jsonschema.Schema {
 63		t.Helper()
 64	
 65		repoRoot := benchRepoRoot(t)
 66		rawSchema, err := os.ReadFile(filepath.Join(repoRoot, "scripts", "benchmark", "benchmark-evidence.schema.json"))
 67		if err != nil {
 68			t.Fatalf("read benchmark evidence schema: %v", err)
 69		}
 70	
 71		compiler := jsonschema.NewCompiler()
 72		compiler.AssertFormat = true
 73		if err := compiler.AddResource("benchmark-evidence.schema.json", bytes.NewReader(rawSchema)); err != nil {
 74			t.Fatalf("add benchmark evidence schema: %v", err)
 75		}
 76		schema, err := compiler.Compile("benchmark-evidence.schema.json")
 77		if err != nil {
 78			t.Fatalf("compile benchmark evidence schema: %v", err)
 79		}
 80		return schema
 81	}
