 83	func loadBenchmarkEvidenceFixture(t *testing.T, name string) map[string]any {
 84		t.Helper()
 85	
 86		repoRoot := benchRepoRoot(t)
 87		raw, err := os.ReadFile(filepath.Join(repoRoot, "cmd", "bench", "testdata", "benchmark-evidence", name))
 88		if err != nil {
 89			t.Fatalf("read fixture %s: %v", name, err)
 90		}
 91	
 92		dec := json.NewDecoder(bytes.NewReader(raw))
 93		dec.UseNumber()
 94		var doc map[string]any
 95		if err := dec.Decode(&doc); err != nil {
 96			t.Fatalf("parse fixture %s: %v", name, err)
 97		}
 98		return doc
 99	}
