101	func assertString(t *testing.T, doc map[string]any, path, want string) {
102		t.Helper()
103		got, ok := lookupPath(doc, path)
104		if !ok {
105			t.Fatalf("missing %s", path)
106		}
107		str, ok := got.(string)
108		if !ok {
109			t.Fatalf("%s = %T, want string", path, got)
110		}
111		if str != want {
112			t.Fatalf("%s = %q, want %q", path, str, want)
113		}
114	}
115	
116	func assertBool(t *testing.T, doc map[string]any, path string, want bool) {
117		t.Helper()
118		got, ok := lookupPath(doc, path)
119		if !ok {
120			t.Fatalf("missing %s", path)
121		}
122		b, ok := got.(bool)
123		if !ok {
124			t.Fatalf("%s = %T, want bool", path, got)
125		}
126		if b != want {
127			t.Fatalf("%s = %t, want %t", path, b, want)
128		}
129	}
130	
131	func lookupPath(doc map[string]any, path string) (any, bool) {
132		var cur any = doc
133		for _, segment := range bytes.Split([]byte(path), []byte(".")) {
134			m, ok := cur.(map[string]any)
135			if !ok {
136				return nil, false
137			}
138			next, ok := m[string(segment)]
139			if !ok {
140				return nil, false
141			}
142			cur = next
143		}
144		return cur, true
145	}
